function longestWord(sentence) {
  var words = sentence.split(" ");
  var longest = "";
  words.forEach(function (w) {
    if (w.length > longest.length) {
      longest = w;
    }
  });
  return longest;
}

console.log(longestWord("blue sky wins"));
